/**
 * NumberValue：显示一个格式化的数字，可以滚动到新值（ADR 0021 的 roll 预设）。
 * 做法：rAF 加 easeOutCubic，进入视口才开始，可错峰起跳；reduced-motion 下直接显示终值。
 * 格式化用注册表的 formatNumber（zh-CN）；纯逻辑在 number-value-model.ts。
 */
import { cn } from "cn";
import {
  type ComponentProps,
  type RefObject,
  useEffect,
  useRef,
  useState,
  useSyncExternalStore,
} from "react";

import {
  fractionDigitsFor,
  type NumberMotion,
  prefersReducedMotion,
  rollDuration,
  rollValue,
} from "@/components/ui/number-value-model";
import { formatNumber } from "@/lib/format";

const REDUCED_QUERY = "(prefers-reduced-motion: reduce)";

function matchMediaOf(): ((query: string) => MediaQueryList) | undefined {
  return typeof window === "undefined" || typeof window.matchMedia !== "function"
    ? undefined
    : (query) => window.matchMedia(query);
}

function subscribeReduced(onChange: () => void): () => void {
  const query = matchMediaOf()?.(REDUCED_QUERY);
  if (!query) return () => {};
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
}

/** 系统是否要求减弱动态效果；跟着系统设置实时变。 */
function useReducedMotion(): boolean {
  return useSyncExternalStore(
    subscribeReduced,
    () => prefersReducedMotion(matchMediaOf()),
    () => false,
  );
}

/** 元素是否进入过视口（只触发一次）。没有 IntersectionObserver 时视为已进入。 */
function useInViewOnce(ref: RefObject<Element | null>, enabled: boolean): boolean {
  const [seen, setSeen] = useState(!enabled);
  useEffect(() => {
    if (seen) return;
    const element = ref.current;
    if (!element || typeof IntersectionObserver !== "function") {
      setSeen(true);
      return;
    }
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((entry) => entry.isIntersecting)) {
          setSeen(true);
          observer.disconnect();
        }
      },
      { threshold: 0.5 },
    );
    observer.observe(element);
    return () => observer.disconnect();
  }, [ref, seen]);
  return seen;
}

type NumberValueProps = Omit<ComponentProps<"span">, "children"> & {
  /** 要显示的数。 */
  value: number;
  /**
   * 动效预设（ADR 0021）。缺省 `roll`。
   * - `roll`：首次进入视口时从 0 滚到 value，之后每次 value 变化从当前显示的值滚到新值。
   * - `none`：直接显示 value。
   */
  motion?: NumberMotion;
  /** 滚动时长（毫秒）。缺省取 --motion-roll-duration（1200ms）。 */
  duration?: number;
  /** 起跳延迟（毫秒）。一排指标卡错开 40–60ms，扫过去像一道波；延迟属于版面，由调用方给。 */
  delay?: number;
  /** 进入视口才开始，缺省 true。 */
  startOnView?: boolean;
  /** 传给 formatNumber 的选项，如百分比、固定小数位。 */
  formatOptions?: Intl.NumberFormatOptions;
};

function NumberValue({
  value,
  motion = "roll",
  duration,
  delay = 0,
  startOnView = true,
  formatOptions,
  className,
  ...props
}: NumberValueProps) {
  const ref = useRef<HTMLSpanElement>(null);
  const reduced = useReducedMotion();
  const inView = useInViewOnce(ref, startOnView && motion === "roll");
  const animate = motion === "roll" && !reduced;
  const [display, setDisplay] = useState(() => (animate ? 0 : value));
  /** 当前画面上的值：值在滚动中途又变了，就从这里接着滚。 */
  const shown = useRef(display);

  useEffect(() => {
    if (!inView) return;
    const from = shown.current;
    const element = ref.current;
    const ms = rollDuration({
      motion,
      reduced,
      from,
      to: value,
      duration,
      cssDuration: element
        ? getComputedStyle(element).getPropertyValue("--motion-roll-duration")
        : null,
    });
    const show = (next: number) => {
      shown.current = next;
      setDisplay(next);
    };
    if (ms === 0) {
      show(value);
      return;
    }
    const decimals = fractionDigitsFor(value, formatOptions);
    let frame = 0;
    const play = () => {
      const startedAt = performance.now();
      const tick = (now: number) => {
        const progress = Math.min(1, (now - startedAt) / ms);
        show(rollValue(from, value, progress, decimals));
        if (progress < 1) frame = requestAnimationFrame(tick);
      };
      frame = requestAnimationFrame(tick);
    };
    // 延迟期间卸载时，定时器与已排的帧都要清掉。
    const timer = delay > 0 ? setTimeout(play, delay) : undefined;
    if (timer === undefined) play();
    return () => {
      clearTimeout(timer);
      cancelAnimationFrame(frame);
    };
  }, [value, motion, reduced, duration, delay, inView, formatOptions]);

  return (
    <span
      ref={ref}
      data-slot="number-value"
      data-motion={motion}
      className={cn("tabular-nums", className)}
      {...props}
    >
      <span aria-hidden="true">{formatNumber(display, formatOptions)}</span>
      <span className="sr-only">{formatNumber(value, formatOptions)}</span>
    </span>
  );
}

export { NumberValue, type NumberValueProps };

/**
 * NumberValue 的纯逻辑（ADR 0021 的 roll 预设）：缓动、插值、取整、时长与 reduced-motion 判断。
 * 不依赖 React 与 DOM，`node --test` 直接测（number-value-model.test.mjs）。
 */

/** roll 的缺省时长（毫秒）。与 base.css 的 --motion-roll-duration 一致；读不到该变量时用它。 */
export const ROLL_DURATION = 1200;

/** 起步快、收尾慢：easeOutCubic。 */
export function easeOutCubic(progress: number): number {
  const t = Math.min(1, Math.max(0, progress));
  return 1 - (1 - t) ** 3;
}

/** 一个数的小数位数：1284 → 0，12.5 → 1，0.125 → 3。 */
export function decimalsOf(value: number): number {
  if (!Number.isFinite(value) || Number.isInteger(value)) return 0;
  const text = String(value);
  const exponent = /e-(\d+)$/.exec(text);
  if (exponent) return Number(exponent[1]);
  return text.split(".")[1]?.length ?? 0;
}

/**
 * 中间帧取整到几位小数，免得滚动时冒出终值没有的小数位。
 * 写了 maximumFractionDigits 就按它，否则按目标值的小数位（最多 3 位，与 Intl 的缺省一致）；
 * 百分比显示时乘了 100，所以再多两位。
 */
export function fractionDigitsFor(value: number, options?: Intl.NumberFormatOptions): number {
  if (options?.style === "percent") return (options.maximumFractionDigits ?? 0) + 2;
  return options?.maximumFractionDigits ?? Math.min(decimalsOf(value), 3);
}

/**
 * 第 progress（0–1）帧显示的值：按 easeOutCubic 从 from 走到 to，取到 decimals 位小数。
 * progress ≥ 1 时精确等于 to，不受取整影响。
 */
export function rollValue(from: number, to: number, progress: number, decimals: number): number {
  if (progress >= 1) return to;
  const raw = from + (to - from) * easeOutCubic(progress);
  const factor = 10 ** decimals;
  return Math.round(raw * factor) / factor;
}

/** CSS 时长文本 → 毫秒：`1200ms` → 1200，`1.2s` → 1200，`0s` → 0；读不懂返回 null。 */
export function parseDuration(text: string | null | undefined): number | null {
  const match = /^\s*(-?[\d.]+)(ms|s)\s*$/.exec(text ?? "");
  if (!match) return null;
  const value = Number(match[1]) * (match[2] === "s" ? 1000 : 1);
  return Number.isFinite(value) && value >= 0 ? value : null;
}

/** 系统是否要求减弱动态效果。没有 matchMedia（测试、SSR、旧浏览器）时视为不要求。 */
export function prefersReducedMotion(
  matchMedia: ((query: string) => { matches: boolean }) | undefined,
): boolean {
  if (typeof matchMedia !== "function") return false;
  return matchMedia("(prefers-reduced-motion: reduce)").matches;
}

export type NumberMotion = "none" | "roll";

/**
 * 这次值变化要滚多久（毫秒）；0 表示直接显示终值。
 * motion 为 none、要求减弱动态效果、起止相同、时长不为正，都直接显示。
 * 时长优先取调用方传的 duration，其次取 CSS 变量 --motion-roll-duration，都没有用 ROLL_DURATION。
 */
export function rollDuration({
  motion,
  reduced,
  from,
  to,
  duration,
  cssDuration,
}: {
  motion: NumberMotion;
  reduced: boolean;
  from: number;
  to: number;
  duration?: number | undefined;
  cssDuration?: string | null | undefined;
}): number {
  if (motion === "none" || reduced || from === to) return 0;
  const ms = duration ?? parseDuration(cssDuration) ?? ROLL_DURATION;
  return ms > 0 ? ms : 0;
}
